export const TYPE = 'regular'




export function BookmarkIcon({
  width,
  height,
  color,
  borderColor,
  styles,
  type,
  opacity = 0,
}) {
  if (type == 'home' || type == 'Home') {
    color = '#FFFF11';
    borderColor = '#000000';
  } else if (type == 'Plans' || type == 'plans') {
    color = '#5F77B6';
    borderColor = '#5F77B6';
  } else if (type == 'Watching' || type == 'watching') {
    color = '#FFEA4F';
    borderColor = '#D6AA63';
  } else if (type == 'Viewed' || type == 'viewed') {
    color = '#ADD8E6';
    borderColor = '#00B0E9';
  } else if (type == 'Dropped' || type == 'dropped') {
    color = '#FF2511';
    borderColor = '#E4837A';
  } else {
    color = '#9E9E9E';
    borderColor = '#9E9E9E';
    opacity = 0.5;
  }
  if (opacity != 0) {
    styles = {...styles};
  }
  return (
    <Svg
      width={width}
      height={height}
      viewBox="0 0 64 64"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      style={styles}>
      <Path
        d="M16 15.9998C16 13.0543 18.3878 10.6665 21.3333 10.6665H42.6667C45.6122 10.6665 48 13.0543 48 15.9998V55.9998L32 39.9998L16 55.9998V15.9998Z"
        fill={color}
        fill-opacity="0.15"
        opacity={opacity}
      />
      <Path
        d="M16 15.9998C16 13.0543 18.3878 10.6665 21.3333 10.6665H42.6667C45.6122 10.6665 48 13.0543 48 15.9998V55.9998L32 39.9998L16 55.9998V15.9998Z"
        stroke={borderColor}
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin="round"
      />
    </Svg>
  );
}
